import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, random } from '../remotionShim';


export type LightLeakTransitionProps = Record<string, any>;

// Deterministic particle generator using a static seed to avoid flickering across threads
const generateParticles = (seed: string, count: number) => {
  return Array.from({ length: count }).map((_, i) => {
    const xSeed = `${seed}-x-${i}`;
    const ySeed = `${seed}-y-${i}`;
    const sizeSeed = `${seed}-size-${i}`;
    const delaySeed = `${seed}-delay-${i}`;
    const speedSeed = `${seed}-speed-${i}`;

    return {
      x: random(xSeed),
      y: random(ySeed),
      size: random(sizeSeed) * 20 + 5,
      delay: random(delaySeed) * 0.4, // Normalized delay up to 40% of duration
      speed: random(speedSeed) * 0.6 + 0.4,
    };
  });
};

const LightLeakTransition: React.FC<LightLeakTransitionProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 2,
  primaryColor = "#ff3300",
  secondaryColor = "#ffaa00",
  accentColor = "#ffffff",
  leakIntensity = 1.2,
  speedMultiplier = 1.5,
  leakDirection = "left-to-right",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const totalFrames = durationInSeconds * fps;
  const progress = frame / totalFrames;

  // Base setup to respect background options
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Faster transition timing utilizing a bell curve curve for overlay peaks
  const adjustedProgress = Math.min(1, Math.max(0, progress * speedMultiplier));
  
  // Transition peak occurs around 40-50% mark
  const opacity = interpolate(
    adjustedProgress,
    [0, 0.35, 0.45, 0.55, 1],
    [0, 0.85 * leakIntensity, 1 * leakIntensity, 0.85 * leakIntensity, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Dynamic light position sweeps across screen based on selected direction
  const sweepPosition = interpolate(
    adjustedProgress,
    [0, 1],
    leakDirection === "left-to-right" ? [-50, 150] : [150, -50],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Static list of flare particles mapped deterministically
  const particles = generateParticles("night-club-leak-particles", 40);

  // Styling transitions for night-club style energetic movement
  const scale = interpolate(adjustedProgress, [0, 0.5, 1], [0.9, 1.2, 1.35]);
  const blurValue = interpolate(adjustedProgress, [0, 0.5, 1], [40, 80, 50]);

  // CSS Linear gradients representing the cinematic anamorphic streaks and leaks
  const renderLeakGradients = () => {
    if (leakDirection === "radial-burst") {
      const radius = interpolate(adjustedProgress, [0, 0.5, 1], [10, 120, 200]);
      return (
        <div
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            transition: "none",
            background: `radial-gradient(circle, ${accentColor} 0%, ${secondaryColor} ${radius * 0.3}%, ${primaryColor} ${radius}%, transparent 80%)`,
            mixBlendMode: "screen",
          }}
        />
      );
    }

    // Default Linear Sweep
    return (
      <>
        {/* Soft primary glow */}
        <div
          style={{
            position: "absolute",
            width: "150%",
            height: "100%",
            left: `${sweepPosition - 25}%`,
            transition: "none",
            background: `linear-gradient(90deg, transparent 10%, ${primaryColor} 45%, ${secondaryColor} 55%, transparent 90%)`,
            mixBlendMode: "screen",
            opacity: 0.8,
          }}
        />
        {/* Intense hot core streak */}
        <div
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            left: `${sweepPosition}%`,
            transition: "none",
            background: `linear-gradient(90deg, transparent 30%, ${secondaryColor} 48%, ${accentColor} 50%, ${secondaryColor} 52%, transparent 70%)`,
            mixBlendMode: "screen",
            opacity: 0.9,
          }}
        />
        {/* Extra horizontal anamorphic glow bands matching the reference image */}
        <div
          style={{
            position: "absolute",
            width: "100%",
            height: "20%",
            top: "40%",
            left: `${sweepPosition - 10}%`,
            transition: "none",
            background: `linear-gradient(90deg, transparent, ${secondaryColor}, ${accentColor}, transparent)`,
            mixBlendMode: "screen",
            filter: "blur(20px)",
            opacity: 0.5,
          }}
        />
      </>
    );
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      <div
        style={{
          width: "100%",
          height: "100%",
          opacity,
          transform: `scale(${scale})`,
          filter: `blur(${blurValue}px)`,
          position: "relative",
          transition: "none",
        }}
      >
        {/* Base Cinematic Light Leak Gradients */}
        {renderLeakGradients()}

        {/* Dynamic Light Dust / Particles overlaying the sweep for Club Energy */}
        {particles.map((particle, index) => {
          // Animate particle coordinates and scale
          const pProgress = Math.min(1, Math.max(0, (adjustedProgress - particle.delay) * particle.speed));
          const pOpacity = interpolate(pProgress, [0, 0.4, 0.8, 1], [0, 0.8, 0.8, 0]);
          
          // Particles burst outward/upward dynamically
          const pX = width * particle.x + (pProgress - 0.5) * 200;
          const pY = height * particle.y - pProgress * 300;
          const pScale = interpolate(pProgress, [0, 1], [0.5, 2.5]);

          return (
            <div
              key={index}
              style={{
                position: "absolute",
                left: pX,
                top: pY,
                width: particle.size,
                height: particle.size,
                borderRadius: "50%",
                backgroundColor: index % 3 === 0 ? accentColor : index % 2 === 0 ? secondaryColor : primaryColor,
                opacity: pOpacity,
                transform: `scale(${pScale})`,
                mixBlendMode: "screen",
                boxShadow: `0 0 ${particle.size * 2}px ${secondaryColor}`,
                transition: "none",
              }}
            />
          );
        })}

        {/* Edge Vignette Leak Overlay */}
        <div
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            background: `radial-gradient(circle, transparent 40%, ${primaryColor}44 85%, #000000cc 100%)`,
            mixBlendMode: "color-dodge",
            transition: "none",
          }}
        />
      </div>
    </AbsoluteFill>
  );
};

export default LightLeakTransition;